const item = $input.item;
const content = item.json.content || {};
const event = content.event;
let msg = "";

// Helpers para formatação de dados
function formatTS(ts) {
  if (!ts) return "N/A";
  try {
    const d = new Date(ts);
    if (isNaN(d.getTime())) return ts;
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = d.getFullYear();
    const hours = String(d.getHours()).padStart(2, '0');
    const minutes = String(d.getMinutes()).padStart(2, '0');
    const seconds = String(d.getSeconds()).padStart(2, '0');
    return `${day}/${month}/${year} ${hours}:${minutes}:${seconds}`;
  } catch {
    return ts;
  }
}

function cleanIps(ipStr) {
  if (!ipStr) return "N/A";
  return ipStr.split("").filter(c => c !== "[" && c !== "]" && c !== "'").join("").split(",").map(s => s.trim()).join(", ");
}

if (event === "incident_opened") {
  const typeLabel = content.incident_type === "SERVICE_DEGRADED" ? "⚠️ INSTABILIDADE" : "🔴 INDISPONIBILIDADE";
  msg = `🚨 <b>[NETSPOT - INCIDENTE ABERTO]</b>\n` +
        `<b>Status:</b> ${typeLabel}\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Dispositivo:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Endereço IP:</b> <code>${content.host_address}</code>\n` +
        `⚙️ <b>Monitor:</b> <code>${content.check_used}</code>\n` +
        `⏱️ <b>Horário:</b> <code>${formatTS(content.started_time)}</code>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `💬 <b>Diagnóstico de Falha:</b>\n` +
        `<code>${content.reason || "Sem descrição de erro"}</code>`;
} else if (event === "incident_closed") {
  const duration = content.duration_seconds || 0;
  const hours = Math.floor(duration / 3600);
  const minutes = Math.floor((duration % 3600) / 60);
  const seconds = duration % 60;
  const durationStr = `${hours}h ${minutes}m ${seconds}s`;

  msg = `✅ <b>[NETSPOT - INCIDENTE RESOLVIDO]</b>\n` +
        `<b>Status:</b> 🟢 ONLINE (Serviço normalizado)\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Dispositivo:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Endereço IP:</b> <code>${content.host_address}</code>\n` +
        `⏱️ <b>Tempo Offline:</b> <code>${durationStr}</code>\n` +
        `⏱️ <b>Recuperado em:</b> <code>${formatTS(content.ended_time)}</code>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `✨ <i>O serviço voltou a responder normalmente e a estabilidade foi restabelecida.</i>`;
} else if (event === "dns_change") {
  msg = `🔄 <b>[NETSPOT - IP ALTERADO NO DNS]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Dispositivo:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Domínio/Host:</b> <code>${content.host_address}</code>\n` +
        `⏱️ <b>Detectado em:</b> <code>${formatTS(content.timestamp)}</code>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `❌ <b>IP Anterior:</b> <code>${content.old_ip || "N/A"}</code>\n` +
        `✅ <b>Novo IP:</b> <code>${cleanIps(content.new_ip)}</code>`;
} else if (event === "dns_ttl_low") {
  msg = `⚠️ <b>[NETSPOT - ALERTA: TTL BAIXO]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Dispositivo:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Domínio/Host:</b> <code>${content.host_address}</code>\n` +
        `⏳ <b>Valor do TTL:</b> <code>${content.ttl}s</code> (Crítico)\n` +
        `⏱️ <b>Horário:</b> <code>${formatTS(content.timestamp)}</code>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `💡 <i>O TTL do DNS está abaixo do limite recomendado, o que pode causar instabilidades de cache ou propagação lenta.</i>`;
} else if (event === "health_critical") {
  msg = `❤️‍🩹 <b>[NETSPOT - ALERTA: SAÚDE CRÍTICA]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Dispositivo:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Endereço IP:</b> <code>${content.host_address}</code>\n` +
        `📊 <b>Score de Saúde:</b> <code>${content.health_score}%</code>\n` +
        `⏱️ <b>Horário:</b> <code>${formatTS(content.timestamp)}</code>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `🚨 <b>Atenção:</b> <i>Este dispositivo atingiu um nível crítico de integridade e requer atenção imediata.</i>`;
} else if (event === "preventive_alert") {
  msg = `⚠️ <b>[NETSPOT - ALERTA PREVENTIVO]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Dispositivo:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Endereço IP:</b> <code>${content.host_address}</code>\n` +
        `🚨 <b>Métrica:</b> <code>${content.condition}</code>\n` +
        `⏱️ <b>Horário:</b> <code>${formatTS(content.timestamp)}</code>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `📊 <b>Detalhes do Diagnóstico:</b>\n` +
        `<code>${content.details || "Sem detalhes da métrica"}</code>`;
} else if (event === "failure_confirmed") {
  msg = `❌ <b>[NETSPOT - FALHA CONFIRMADA]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Dispositivo:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Endereço IP:</b> <code>${content.host_address}</code>\n` +
        `⚙️ <b>Monitor:</b> <code>${content.check_used}</code>\n` +
        `🔄 <b>Mudança de Estado:</b> <code>${content.old_status} ➔ ${content.new_status}</code>\n` +
        `📉 <b>Falhas Consecutivas:</b> <code>${content.fail_streak}</code>\n` +
        `⏱️ <b>Horário:</b> <code>${formatTS(content.timestamp)}</code>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `⚠️ <i>O limite de tentativas de falha configurado foi excedido. O host foi marcado como indisponível.</i>`;
} else if (event === "recovery") {
  msg = `🟢 <b>[NETSPOT - DISPOSITIVO RECUPERADO]</b>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `🖥️ <b>Dispositivo:</b> <code>${content.host_name}</code>\n` +
        `🌐 <b>Endereço IP:</b> <code>${content.host_address}</code>\n` +
        `🔄 <b>Mudança de Estado:</b> <code>${content.old_status} ➔ UP</code>\n` +
        `⏱️ <b>Horário:</b> <code>${formatTS(content.timestamp)}</code>\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `✨ <i>Dispositivo recuperado com sucesso e todos os serviços estão normalizados.</i>`;
} else {
  msg = `✉️ <b>[NOTIFICAÇÃO NETSPOT]</b>\n\n` +
        `${content.message || JSON.stringify(item.json)}`;
}

item.json.formatted_message = msg;
return item;
